module linked_list_traversal (
    input wire clk,
    input wire rst,
    input wire [3:0] data_in,
    input wire insert,
    input wire traverse,
    output reg [3:0] data_out,
    output reg valid
);
    parameter MAX_NODES = 5;

    // Node structure
    reg [3:0] nodes [0:MAX_NODES-1];
    reg [2:0] head;
    reg [2:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            head <= 0;
            count <= 0;
            valid <= 0;
        end else begin
            if (insert && count < MAX_NODES) begin
                nodes[count] <= data_in;
                count <= count + 1;
            end
            if (traverse && head < count) begin
                data_out <= nodes[head];
                valid <= 1;
                head <= head + 1;
            end else begin
                valid <= 0;
            end
        end
    end
endmodule

