module deserializer_16bit(  
    input wire clk,  
    input wire reset,  
    input wire serial_in,  
    output reg [15:0] parallel_out  
);  
    reg [3:0] bit_count; // Counter for how many bits have been received  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            parallel_out <= 16'b0;  
            bit_count <= 4'b0;  
        end else begin  
            parallel_out <= {parallel_out[14:0], serial_in}; // Shift left and add new bit  
            if (bit_count < 4'd15)  
                bit_count <= bit_count + 1;  
        end  
    end  
endmodule

