module butterworth_filter(  
    input clk,  
    input rst,  
    input signed [15:0] x_in,  
    output reg signed [15:0] y_out  
);  
    reg signed [15:0] x_prev1, x_prev2;  
    reg signed [15:0] y_prev1, y_prev2;  
    parameter signed [15:0] b0 = 16'h1F; // Example coefficients  
    parameter signed [15:0] b1 = 16'h2F;  
    parameter signed [15:0] b2 = 16'h1F;  
    parameter signed [15:0] a1 = 16'h0F;  
    parameter signed [15:0] a2 = 16'h0F;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            x_prev1 <= 0;  
            x_prev2 <= 0;  
            y_prev1 <= 0;  
            y_prev2 <= 0;  
            y_out <= 0;  
        end else begin  
            y_out <= (b0 * x_in + b1 * x_prev1 + b2 * x_prev2 - a1 * y_prev1 - a2 * y_prev2) >> 8;  
            x_prev2 <= x_prev1;  
            x_prev1 <= x_in;  
            y_prev2 <= y_prev1;  
            y_prev1 <= y_out;  
        end  
    end  
endmodule

