module dma_controller (
    input clk,
    input reset,
    input start,
    input [7:0] src_addr,
    input [7:0] dest_addr,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg done
);

    reg [7:0] memory [255:0]; // Simple memory array
    reg [7:0] current_addr;
    reg transferring;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            done <= 0;
            transferring <= 0;
        end else begin
            if (start && !transferring) begin
                current_addr <= src_addr;
                transferring <= 1;
                done <= 0;
            end

            if (transferring) begin
                data_out <= memory[current_addr];
                memory[dest_addr] <= data_out; // Simulate data transfer
                current_addr <= current_addr + 1;

                if (current_addr == src_addr + 1) begin // Assume transferring 1 byte
                    transferring <= 0;
                    done <= 1;
                end
            end
        end
    end
endmodule

