module uart_tx (
    input clk,
    input rst,
    input tx_en,
    input [7:0] data_in,
    output reg tx_out
);
    parameter CLK_FREQ = 1000000; // 1 MHz
    parameter BAUD_RATE = 9600;
    parameter BIT_TIME = CLK_FREQ / BAUD_RATE; // Clock cycles for one bit
    reg [3:0] bit_index;
    reg [15:0] counter;
    reg transmitting;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx_out <= 1; // Idle state is high
            bit_index <= 0;
            counter <= 0;
            transmitting <= 0;
        end else if (transmitting) begin
            if (counter < BIT_TIME - 1) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                if (bit_index < 10) begin
                    case (bit_index)
                        0: tx_out <= 0; // Start bit
                        1: tx_out <= data_in[0];
                        2: tx_out <= data_in[1];
                        3: tx_out <= data_in[2];
                        4: tx_out <= data_in[3];
                        5: tx_out <= data_in[4];
                        6: tx_out <= data_in[5];
                        7: tx_out <= data_in[6];
                        8: tx_out <= data_in[7];
                        9: tx_out <= 1; // Stop bit
                    endcase
                    bit_index <= bit_index + 1;
                end else begin
                    transmitting <= 0; // Transmission complete
                    bit_index <= 0;
                end
            end
        end else if (tx_en) begin
            transmitting <= 1;
            counter <= 0;
        end
    end
endmodule

