module pll (
    input wire clk_in,        // Input clock
    input wire reset,         // Reset signal
    output reg clk_out        // Output clock
);

reg [1:0] divider;            // Frequency divider
wire phase_detected;          // Phase detection signal

// Frequency Divider
always @(posedge clk_in or posedge reset) begin
    if (reset) begin
        divider <= 2'b00;
        clk_out <= 0;
    end else begin
        divider <= divider + 1;
        if (divider == 2'b01) begin
            clk_out <= ~clk_out;
        end
    end
end

endmodule

