module serializer_16bit (  
    input wire clk,  
    input wire reset,  
    input wire valid,  
    input wire [15:0] parallel_in,  
    output reg serial_out  
);  
    reg [3:0] bit_counter;  
    reg [15:0] data;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            serial_out <= 0;  
            bit_counter <= 0;  
            data <= 0;  
        end else if (valid) begin  
            data <= parallel_in;  
            bit_counter <= 15;  
        end else if (bit_counter > 0) begin  
            serial_out <= data[bit_counter];  
            bit_counter <= bit_counter - 1;  
        end  
    end  
endmodule

