module uart_transmitter(  
    input wire clk,  
    input wire start_bit,  
    input wire [7:0] data,  
    input wire stop_bit,  
    output reg tx,  
    output reg busy  
);  
    reg [3:0] bit_index;  
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit  
    reg [15:0] baud_counter;  
    parameter BAUD_RATE = 16'd104; // Assuming 16 MHz clock, for 9600 baud  

    always @(posedge clk) begin  
        if (!busy) begin  
            if (start_bit) begin  
                shift_reg <= {stop_bit, data, 1'b0}; // Load data with stop bit  
                bit_index <= 0;  
                busy <= 1;  
                baud_counter <= 0;  
            end  
        end else begin  
            if (baud_counter < BAUD_RATE) begin  
                baud_counter <= baud_counter + 1;  
            end else begin  
                baud_counter <= 0;  
                tx <= shift_reg[bit_index];  
                if (bit_index < 9)  
                    bit_index <= bit_index + 1;  
                else begin  
                    busy <= 0;  
                    bit_index <= 0;  
                end  
            end  
        end  
    end  
endmodule

