module watchdog_timer (
    input wire clk,
    input wire reset,
    output reg timeout
);
    reg [3:0] counter; // 4-bit counter (can count up to 15)

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            timeout <= 0;
        end else begin
            if (counter < 10) begin
                counter <= counter + 1;
                timeout <= 0;
            end else begin
                timeout <= 1; // Assert timeout if counter reaches 10
            end
        end
    end
endmodule

