module pitch_detector (
    input clk,
    input reset,
    input [3:0] sample,
    output reg [3:0] frequency
);
    reg [3:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            frequency <= 4'b0000;
            count <= 4'b0000;
        end else begin
            if (sample > frequency) begin
                frequency <= sample;
            end
            count <= count + 1;
            if (count == 4'b1111) begin // Simulate detecting every 16 samples
                count <= 4'b0000;
            end
        end
    end
endmodule

