module restoring_divider(
    input clk,
    input rst,
    input start,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);
    reg [15:0] temp_dividend;
    reg [15:0] temp_quotient;
    reg [4:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            quotient <= 16'b0;
            remainder <= 16'b0;
            temp_dividend <= 16'b0;
            temp_quotient <= 16'b0;
            count <= 5'b0;
            done <= 1'b0;
        end else if (start) begin
            temp_dividend <= dividend;
            temp_quotient <= 16'b0;
            count <= 5'd16;
            done <= 1'b0;
        end else if (count > 0) begin
            temp_quotient <= {temp_quotient[14:0], 1'b1};
            temp_dividend <= {temp_dividend[14:0], 1'b0}; // Shift left
            if (temp_dividend >= divisor) begin
                temp_dividend <= temp_dividend - divisor; // Subtract
            end else begin
                temp_quotient <= {temp_quotient[14:0], 1'b0};
            end
            count <= count - 1;
        end else begin
            quotient <= temp_quotient;
            remainder <= temp_dividend;
            done <= 1'b1;
        end
    end
endmodule

