module watchdog_timer (  
    input clk,  
    input reset,  
    input [3:0] timeout_period,  
    output reg timeout  
);  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else if (counter < timeout_period) begin  
            counter <= counter + 1;  
            timeout <= 0;  
        end else begin  
            timeout <= 1;  
        end  
    end  
endmodule

